      "ballot_id": "B009",
      "proposed_laureates": [
        "Shinji Yuasa",
        "Stuart S. P. Parkin",
        "William H. Butler"
      ],
      "assessment": {
        "nobel_worthiness": "Large tunnel magnetoresistance in crystalline MgO junctions combined a striking physical effect with a practical foundation for magnetic memory and read heads.",
        "attribution": "Yuasa and Parkin independently demonstrated the large effect in devices, while Butler explained the symmetry-based filtering that made it possible.",
        "maturity": "The result has been replicated, understood in substantial detail, and incorporated into mature spintronic technology.",
        "uncertainties": [
          "The relative weight of the independent experimental demonstrations and the theoretical prediction merits careful calibration."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Charles L. Kane",
        "Laurens W. Molenkamp",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators established a new organizing principle for electronic states and led to quantized transport phenomena with deep conceptual and technological significance.",
        "attribution": "Kane's theory and the experimental work of Molenkamp and Xue connect the predicted quantum spin Hall and quantum anomalous Hall effects to their realization.",
        "maturity": "The basic effects are well established, although materials quality and the range of robust operating conditions remain active research topics.",
        "uncertainties": [
          "The broad label covers several discoveries and experimental milestones, so the precise scope of a prize would need definition."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made a powerful, broadly useful framework for understanding local correlations in materials and transformed the study of strongly correlated electrons.",
        "attribution": "These theorists developed and established the method and its central applications; the conceptual contribution is unusually well suited to a shared theory prize.",
        "maturity": "The framework has been used and extended for decades, with extensive comparison to experiments and other computational approaches.",
        "uncertainties": [
          "Its scope is a theoretical method rather than one discrete discovery, and its continuing development complicates the boundary of the contribution."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Ramamoorthy Ramesh",
        "Sang-Wook Cheong",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetically driven ferroelectricity revealed a route to strong coupling between magnetic and electric order, expanding the possibilities for both fundamental physics and materials functionality.",
        "attribution": "Cheong and Tokura were central to identifying and explaining the phenomenon; Ramesh helped establish important multiferroic materials and their properties.",
        "maturity": "The coupling has been demonstrated across material systems and studied extensively, though practical devices remain more limited than the physical concept.",
        "uncertainties": [
          "The proposed discovery combines related advances across materials, mechanisms, and device work, making the exact prize scope and credit division less clear."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "James P. Eisenstein",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Exciton condensation in quantum Hall bilayers offers a compelling realization of collective quantum coherence and unusual counterflow transport in a solid-state system.",
        "attribution": "MacDonald and Girvin helped develop the theoretical picture, while Eisenstein's experiments established the bilayer platform and key signatures.",
        "maturity": "The system has been investigated for many years, but the interpretation and limits of the condensate regime remain subjects of discussion.",
        "uncertainties": [
          "Some observed transport signatures may admit explanations more nuanced than a simple equilibrium exciton condensate."
        ]
      }
    },
    {
      "rank": 7,
